/**
 * 兼容旧路径：/cart-rescue/ → /help/
 * App Store / Partner 旧链接继续可用
 * @author 恒哥
 */
import React, { useEffect } from 'react';
import { navigate } from 'gatsby';
import SEO from '../../components/SEO';

export default function CartRescueRedirect() {
  useEffect(() => {
    navigate('/help/', { replace: true });
  }, []);
  return (
    <SEO
      title="Help Center — Whaleal Cart"
      description="Redirecting to Whaleal Cart Help / FAQ"
      pathname="/cart-rescue"
      noindex
    />
  );
}
